const HL_LEVEL_COUNT = HL_LEVELS.length;

function hlGenerateLevel(levelIndex) {
  const lvl = HL_LEVELS[levelIndex];
  return {
    objects: lvl.o.map(([classIdx, x, y, z, qx, qy, qz, qw]) => ({
      classIdx,
      position: [x / 1000, y / 1000, z / 1000],
      quaternion: [qx / 1000, qy / 1000, qz / 1000, qw / 1000],
    })),
  };
}

/* ══════════════════════════════════════════════════════════
   LIVE GAME — everything below touches THREE/CANNON/document/G and only
   ever runs in the browser; the offline generator never calls any of it.
══════════════════════════════════════════════════════════ */
let hlRenderer = null, hlScene = null, hlCamera = null;
let hlWorld = null, hlRimBody = null;
let hlObjectBodies = [];   // CANNON.Body[] | null (null once swallowed), parallel to level.objects
let hlObjectMeshes = [];   // THREE.Mesh[] | null, parallel to level.objects
let hlHolePitMesh = null;
let hlFallingAnims = [];   // { mesh, t0, duration, x0,y0,z0 } — in-flight "falling into the hole" animations
let hlRafId = null;
let hlLastFrameTime = null;
let hlClearing = false;    // guards against re-firing hlOnLevelCleared while its advance-delay is pending
let hlDragging = false;
let hlDragTargetX = 0, hlDragTargetZ = 0;
let hlRimX = 0, hlRimZ = 0; // live eased rim position (world units)
let hlRaycaster = null;
let hlGroundPlane = null; // THREE.Plane, y=0, for pointer->world raycasting

function hlObjectRadius(classIdx) { return HL_SIZE_CLASSES[classIdx]; }

function hlMakeGeometry(shape, r) {
  switch (shape) {
    case 'box': { const s = r * 1.5; return new THREE.BoxGeometry(s, s, s); }
    case 'sphere': return new THREE.SphereGeometry(r, 12, 10);
    case 'cylinder': return new THREE.CylinderGeometry(r * 0.8, r * 0.8, r * 1.6, 14);
    case 'cone': return new THREE.ConeGeometry(r * 0.9, r * 1.7, 14);
    case 'torus': return new THREE.TorusGeometry(r * 0.6, r * 0.28, 8, 16);
    case 'icosahedron': return new THREE.IcosahedronGeometry(r * 1.05, 0);
    default: return new THREE.SphereGeometry(r, 12, 10);
  }
}

function hlSetupScene() {
  const canvas = document.getElementById('hl-board');
  if (!canvas) return;
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 2);

  if (!hlRenderer) {
    hlRenderer = new THREE.WebGLRenderer({ canvas, antialias: true });
    hlScene = new THREE.Scene();
    hlScene.background = new THREE.Color(0x1b2620);
    const ambient = new THREE.AmbientLight(0xffffff, 0.65);
    const dir = new THREE.DirectionalLight(0xffffff, 0.9);
    dir.position.set(6, 10, 4);
    hlScene.add(ambient, dir);
    hlRaycaster = new THREE.Raycaster();
    hlGroundPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);

    const groundGeo = new THREE.PlaneGeometry((HL_BOARD_HALF + 1) * 2, (HL_BOARD_HALF + 1) * 2);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x2e3c36 });
    const groundMesh = new THREE.Mesh(groundGeo, groundMat);
    groundMesh.rotation.x = -Math.PI / 2;
    hlScene.add(groundMesh);

    const pitGeo = new THREE.CylinderGeometry(1, 1, 0.6, 24, 1, true);
    const pitMat = new THREE.MeshStandardMaterial({ color: 0x05070a, side: THREE.DoubleSide });
    hlHolePitMesh = new THREE.Mesh(pitGeo, pitMat);
    hlScene.add(hlHolePitMesh);
  }

  hlRenderer.setPixelRatio(dpr);
  hlRenderer.setSize(rect.width, rect.height, false);

  const aspect = rect.width / rect.height || 1;
  const frustumSize = HL_BOARD_HALF * 1.85;
  hlCamera = new THREE.OrthographicCamera(
    -frustumSize * aspect, frustumSize * aspect, frustumSize, -frustumSize, 0.1, 100
  );
  hlCamera.position.set(0, HL_BOARD_HALF * 2.1, HL_BOARD_HALF * 2.1);
  hlCamera.lookAt(0, 0, 0);

  hlBindPointerEvents(canvas);
}

function hlBindPointerEvents(canvas) {
  if (canvas.dataset.hlBound) return;
  canvas.dataset.hlBound = '1';
  const ndcFromEvent = e => {
    const rect = canvas.getBoundingClientRect();
    return {
      x: ((e.clientX - rect.left) / rect.width) * 2 - 1,
      y: -((e.clientY - rect.top) / rect.height) * 2 + 1,
    };
  };
  const setTargetFromEvent = e => {
    const ndc = ndcFromEvent(e);
    hlRaycaster.setFromCamera(ndc, hlCamera);
    const hit = new THREE.Vector3();
    if (hlRaycaster.ray.intersectPlane(hlGroundPlane, hit)) {
      hlDragTargetX = Math.max(-HL_BOARD_HALF, Math.min(HL_BOARD_HALF, hit.x));
      hlDragTargetZ = Math.max(-HL_BOARD_HALF, Math.min(HL_BOARD_HALF, hit.z));
    }
  };
  canvas.addEventListener('pointerdown', e => {
    if (!G.hole.unlocked) return;
    hlDragging = true;
    canvas.setPointerCapture(e.pointerId);
    setTargetFromEvent(e);
  });
  canvas.addEventListener('pointermove', e => { if (hlDragging) setTargetFromEvent(e); });
  const endDrag = () => { hlDragging = false; };
  canvas.addEventListener('pointerup', endDrag);
  canvas.addEventListener('pointercancel', endDrag);
}

function hlMakeWallBody(pos, angle) {
  const b = new CANNON.Body({ mass: 0 });
  b.addShape(new CANNON.Plane());
  b.quaternion.setFromAxisAngle(new CANNON.Vec3(0, 1, 0), angle);
  b.position.set(pos[0], pos[1], pos[2]);
  return b;
}

function hlMakeRimShape(radius) {
  return new CANNON.Cylinder(radius, radius, HL_RIM_HEIGHT, 12);
}

// Tears down any previous level's bodies/meshes and builds a fresh physics
// world + scene content for `level`, skipping objects already marked
// swallowed in `swallowedMask` (mid-level resume) and instantiating the
// rest at their baked settled transforms — never re-simulates the drop.
function hlBuildLevelContent(level, levelIndex, swallowedMask, holeClassIdx) {
  hlObjectMeshes.forEach(m => { if (m) hlScene.remove(m); });
  hlFallingAnims.forEach(a => { if (a.mesh) hlScene.remove(a.mesh); });
  hlFallingAnims = [];

  hlWorld = new CANNON.World();
  hlWorld.gravity.set(0, -9.82, 0);
  hlWorld.broadphase = new CANNON.NaiveBroadphase();
  hlWorld.solver.iterations = 10;
  const ground = new CANNON.Body({ mass: 0 });
  ground.addShape(new CANNON.Plane());
  ground.quaternion.setFromAxisAngle(new CANNON.Vec3(1, 0, 0), -Math.PI / 2);
  hlWorld.addBody(ground);
  hlWorld.addBody(hlMakeWallBody([HL_BOARD_HALF + 0.5, 0, 0], -Math.PI / 2));
  hlWorld.addBody(hlMakeWallBody([-HL_BOARD_HALF - 0.5, 0, 0], Math.PI / 2));
  hlWorld.addBody(hlMakeWallBody([0, 0, HL_BOARD_HALF + 0.5], Math.PI));
  hlWorld.addBody(hlMakeWallBody([0, 0, -HL_BOARD_HALF - 0.5], 0));

  hlRimBody = new CANNON.Body({ mass: 0, type: CANNON.Body.KINEMATIC });
  hlRimBody.addShape(hlMakeRimShape(hlObjectRadius(holeClassIdx)));
  hlRimBody.position.set(hlRimX, HL_RIM_HEIGHT / 2, hlRimZ);
  hlWorld.addBody(hlRimBody);

  hlObjectBodies = new Array(level.objects.length).fill(null);
  hlObjectMeshes = new Array(level.objects.length).fill(null);
  level.objects.forEach((obj, i) => {
    if (swallowedMask[i]) return;
    const r = hlObjectRadius(obj.classIdx);
    const body = new CANNON.Body({ mass: Math.max(0.2, r * r * r) });
    body.addShape(new CANNON.Box(new CANNON.Vec3(r, r, r)));
    body.position.set(...obj.position);
    body.quaternion.set(...obj.quaternion);
    body.allowSleep = true;
    body.sleepSpeedLimit = 0.15;
    body.sleepTimeLimit = 0.3;
    body.linearDamping = 0.5;
    body.angularDamping = 0.5;
    hlWorld.addBody(body);
    hlObjectBodies[i] = body;

    const { shape, color } = hlShapeFor(levelIndex, i);
    const mesh = new THREE.Mesh(hlMakeGeometry(shape, r), new THREE.MeshStandardMaterial({ color }));
    mesh.position.set(...obj.position);
    mesh.quaternion.set(...obj.quaternion);
    hlScene.add(mesh);
    hlObjectMeshes[i] = mesh;
  });

  hlUpdateHolePitMesh(holeClassIdx);
}

function hlUpdateHolePitMesh(holeClassIdx) {
  if (!hlHolePitMesh) return;
  const r = hlObjectRadius(holeClassIdx);
  hlHolePitMesh.scale.set(r, 1, r);
  hlHolePitMesh.position.set(hlRimX, -0.05, hlRimZ);
}

/* ══════════════════════════════════════════════════════════
   GAME FLOW — reads/writes G.hole. Mirrors the other three minigames'
   conventions (playOrder queue, question-gated unlock via the shared
   askQuestions(), free same-level restart, stale-index guard against a
   since-regenerated level pool) — only the rendering/physics internals
   changed for v2, not the app-integration plumbing.
══════════════════════════════════════════════════════════ */
function hlRenderInfo(levelIndex) {
  const infoEl = document.getElementById('hl-level-info');
  if (infoEl) infoEl.textContent = `Level ${levelIndex + 1} / ${HL_LEVEL_COUNT}`;
  const overlay = document.getElementById('hl-start-overlay');
  if (overlay) overlay.hidden = !!G.hole.unlocked;
}

function hlStartLevel(levelIndex) {
  const hl = G.hole;
  const level = hlGenerateLevel(levelIndex);
  hl.currentLevelIndex = levelIndex;
  hl.unlocked = false;
  hl.size = 0; // holeClassIdx — see file header for why this is index-based
  hl.swallowedMask = new Array(level.objects.length).fill(false);
  hlClearing = false;
  hlDragging = false;
  hlRimX = 0; hlRimZ = 0;
  hlDragTargetX = 0; hlDragTargetZ = 0;
  hlSetupScene();
  hlBuildLevelContent(level, levelIndex, hl.swallowedMask, hl.size);
  hlRenderInfo(levelIndex);
  saveState();
}

function hlEnsureQueueAndLevel() {
  const hl = G.hole;
  const staleIndex = hl.playOrder.some(i => i >= HL_LEVEL_COUNT) ||
    (hl.currentLevelIndex != null && hl.currentLevelIndex >= HL_LEVEL_COUNT);
  if (!hl.playOrder.length || staleIndex) {
    hl.playOrder = shuffleArray([...Array(HL_LEVEL_COUNT).keys()]);
    hl.playOrderPos = 0;
    hl.currentLevelIndex = null;
  }
  if (hl.currentLevelIndex == null || !hl.swallowedMask.length) {
    hlStartLevel(hl.playOrder[hl.playOrderPos]);
  } else {
    hlClearing = false;
    const level = hlGenerateLevel(hl.currentLevelIndex);
    hlSetupScene();
    hlBuildLevelContent(level, hl.currentLevelIndex, hl.swallowedMask, hl.size);
    hlRenderInfo(hl.currentLevelIndex);
  }
  hlStartLoop();
}

// The paid gate: mirrors wsBuyExtraBottle/plBuyExtraBay/msBuyExtraSlot
// exactly (hasActiveQuestions check + toast, then askQuestions for 1),
// except here it unlocks the whole level rather than one extra capacity
// unit. askQuestions() feeds the Tamagotchi automatically on every correct
// answer (feedTamagotchi(), see js/game.js) — same as every other
// question-spending flow in this app, no extra wiring needed here.
function hlStartAttempt() {
  const hl = G.hole;
  if (hl.currentLevelIndex == null || hl.unlocked) return;
  if (!hasActiveQuestions()) {
    showToast('Keine aktiven Fragen! Aktiviere Kapitel unter 📚.');
    return;
  }
  askQuestions('🕳️ Level starten', 1, () => {
    hl.unlocked = true;
    saveState();
    hlRenderInfo(hl.currentLevelIndex);
  }, null);
}

// Free, like every other minigame's restart: resets progress on the
// CURRENT level only (same baked layout) without re-locking it.
function hlRestartLevel() {
  const hl = G.hole;
  if (hl.currentLevelIndex == null) return;
  const level = hlGenerateLevel(hl.currentLevelIndex);
  hl.size = 0;
  hl.swallowedMask = new Array(level.objects.length).fill(false);
  hlClearing = false;
  hlRimX = 0; hlRimZ = 0;
  hlDragTargetX = 0; hlDragTargetZ = 0;
  hlBuildLevelContent(level, hl.currentLevelIndex, hl.swallowedMask, hl.size);
  hlRenderInfo(hl.currentLevelIndex);
  saveState();
  showToast('🔄 Level neu gestartet.');
}

function hlOnLevelCleared() {
  showToast('🕳️ Level geschafft!');
  saveState();
  setTimeout(hlAdvanceToNextLevel, 900);
}

function hlAdvanceToNextLevel() {
  const hl = G.hole;
  hl.playOrderPos++;
  if (hl.playOrderPos >= hl.playOrder.length) {
    const prevLast = hl.playOrder[hl.playOrder.length - 1];
    const order = shuffleArray([...Array(HL_LEVEL_COUNT).keys()]);
    if (order[0] === prevLast) [order[0], order[1]] = [order[1], order[0]];
    hl.playOrder = order;
    hl.playOrderPos = 0;
  }
  hlStartLevel(hl.playOrder[hl.playOrderPos]);
}

/* ══════════════════════════════════════════════════════════
   TICK — steps physics, syncs meshes, runs the swallow check, animates
   fall-ins, renders. requestAnimationFrame loop like Mosaik's belt, since
   this needs continuous simulation unlike every other screen's
   rebuild-on-tap model.
══════════════════════════════════════════════════════════ */
function hlCheckSwallows(level) {
  const hl = G.hole;
  if (hlClearing) return;
  const holeRadius = hlObjectRadius(hl.size);
  let anySwallowed = false;
  level.objects.forEach((obj, i) => {
    if (hl.swallowedMask[i] || !hlObjectBodies[i]) return;
    if (obj.classIdx > hl.size) return; // doesn't fit yet
    const body = hlObjectBodies[i];
    if (Math.abs(body.position.y - hlObjectRadius(obj.classIdx)) > HL_FLOOR_EPS) return; // not resting at floor
    if (Math.hypot(body.position.x - hlRimX, body.position.z - hlRimZ) > holeRadius) return;

    hl.swallowedMask[i] = true;
    hlWorld.removeBody(body);
    hlObjectBodies[i] = null;
    if (obj.classIdx + 1 > hl.size) {
      hl.size = Math.min(HL_SIZE_CLASSES.length - 1, obj.classIdx + 1);
      hlRimBody.shapes = [];
      hlRimBody.addShape(hlMakeRimShape(hlObjectRadius(hl.size)));
      hlUpdateHolePitMesh(hl.size);
    }
    const mesh = hlObjectMeshes[i];
    hlObjectMeshes[i] = null;
    if (mesh) hlFallingAnims.push({ mesh, t0: performance.now(), duration: 300, x0: mesh.position.x, y0: mesh.position.y, z0: mesh.position.z });
    anySwallowed = true;
  });
  if (anySwallowed) saveState();
  if (hl.swallowedMask.every(Boolean)) { hlClearing = true; hlOnLevelCleared(); }
}

function hlAdvanceFallingAnims() {
  const now = performance.now();
  for (let k = hlFallingAnims.length - 1; k >= 0; k--) {
    const a = hlFallingAnims[k];
    const t = Math.min(1, (now - a.t0) / a.duration);
    a.mesh.position.set(
      a.x0 + (hlRimX - a.x0) * t,
      a.y0 - t * 1.2,
      a.z0 + (hlRimZ - a.z0) * t
    );
    const s = Math.max(0.001, 1 - t);
    a.mesh.scale.set(s, s, s);
    if (t >= 1) {
      hlScene.remove(a.mesh);
      hlFallingAnims.splice(k, 1);
    }
  }
}

function hlStartLoop() {
  if (hlRafId != null) return;
  hlLastFrameTime = null;
  const frame = t => {
    const screenEl = document.getElementById('screen-hole');
    if (!screenEl || screenEl.hidden) { hlRafId = null; hlLastFrameTime = null; return; } // tab switched away — restarted by hlEnsureQueueAndLevel on return
    const hl = G.hole;
    if (hl.currentLevelIndex == null || !hlWorld) { hlRafId = requestAnimationFrame(frame); return; }
    const level = hlGenerateLevel(hl.currentLevelIndex);
    const dtMs = hlLastFrameTime == null ? 0 : Math.min(100, t - hlLastFrameTime);
    hlLastFrameTime = t;
    const dtSec = dtMs / 1000;

    if (hl.unlocked && dtSec > 0) {
      const ease = 1 - Math.pow(0.001, dtSec); // frame-rate-independent "weighty follow"
      hlRimX += (hlDragTargetX - hlRimX) * ease;
      hlRimZ += (hlDragTargetZ - hlRimZ) * ease;
      hlRimBody.position.set(hlRimX, HL_RIM_HEIGHT / 2, hlRimZ);
      hlUpdateHolePitMesh(hl.size);

      hlWorld.step(1 / 60, dtSec, 5);

      level.objects.forEach((obj, i) => {
        const body = hlObjectBodies[i], mesh = hlObjectMeshes[i];
        if (body && mesh) { mesh.position.copy(body.position); mesh.quaternion.copy(body.quaternion); }
      });
      hlCheckSwallows(level);
      hlAdvanceFallingAnims();
    }

    hlRenderer.render(hlScene, hlCamera);
    hlRafId = requestAnimationFrame(frame);
  };
  hlRafId = requestAnimationFrame(frame);
}

if (typeof window !== 'undefined') {
  window.hlEnsureQueueAndLevel = hlEnsureQueueAndLevel;
  window.hlStartAttempt = hlStartAttempt;
  window.hlRestartLevel = hlRestartLevel;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    HL_BOARD_HALF, HL_SIZE_CLASSES, HL_RIM_HEIGHT, HL_FLOOR_EPS,
    HL_LEVELS, HL_LEVEL_COUNT, hlGenerateLevel,
  };
}
